Hypothesis RB_udd_nn : forall w h cm, (0 <= RB_udd w h cm)%Z.
(* [comment removed for export] *)
Hypothesis RB_udd_le1 : forall w h cm, (RB_udd w h cm <= RB_udd w h 1)%Z.

