(* [comment removed for export] *)
Lemma OCC_pw : forall m m' s ret v0 v1 v2 v3 v4 f0 f1, (96 <= s)%Z -> (s < 2 ^ 64)%Z ->
  (forall (b : Z) (n : nat), (s - 64 <= b)%Z -> (b + Z.of_nat n <= s)%Z -> rdn SEGS m' (Z_to_bv 64 b) n = rdn SEGS m (Z_to_bv 64 b) n) ->
