(* [comment removed for export] *)
Definition oc_res (C : lctx) (A A' : AS) (m' : word -> option byte) (regs' : bvmap 5 word) (cv : cmapv) : Prop :=
  (getr regs' 10 = Z_to_bv 64 0 /\ forall q, live A' q = live A q)
  \/ (exists pixd w' h' cd data, getr regs' 10 = Z_to_bv 64 pixd /\ hdr_ok w' h' 1 /\ (1 <= w')%Z /\ (1 <= h')%Z /\
                                 pixt_new C A A' m' pixd w' h' 1 cd data cv).

(* [comment removed for export] *)
Ltac oc_arm LA FMT KF STR RA KONT :=
  lazymatch goal with
  | CK : Cok ?C, HW8 : W ?C ?A6 ?m8 ?md6, S10 : getr ?rS 10 = Z_to_bv 64 3, Hs16 : (?s mod 16 = 0)%Z, PM8s : POSTM ?C ?A ?s ?Mr ?m8, SUB6 : sub_live ?A ?A6,
    CE8 : OCC ?m8 ?s _ _ _ _ _ _ _ _
    |- realizes _ (mkCfg (@mkst (mkFP ?fr8 ?cs8) ?rS _ ?m8 _) ?md6) ?S =>
      let r11 := fresh "r11" in let RUN11 := fresh "RUN11" in let M1' := fresh "M1'" in let M10 := fresh "M10" in let M11 := fresh "M11" in
      let AG11 := fresh "AG11" in
      destruct (LA al_rom (mkFP fr8 cs8) rS m8 S10) as (r11 & RUN11 & M1' & M10 & M11 & AG11);
      eapply rz_msteps; [exact (mp_halted _ (w_pure _ _ _ _ HW8)) | exact (mp_lazy _ (w_pure _ _ _ _ HW8)) | exact RUN11 |];
      apply (lept_stderr1P8_W (fx := mkFP fr8 cs8) C A6 m8 md6 r11 (s - 96) FMT 0x1055c KF 16 (Z_to_bv 64 RA) S CK HW8
               ltac:(csr; reflexivity) ltac:(rewrite <- Zminus_mod_idemp_l, Hs16; reflexivity) ltac:(unfold LSF; lia) ltac:(lia)
               M1' ltac:(red; apply bv_eq; reflexivity) M10 M11 ltac:(kc_clear; cbn; tauto) STR str_oc_proc);
      let m9 := fresh "m9" in let r12 := fresh "r12" in let HW9 := fresh "HW9" in let OUT9 := fresh "OUT9" in let GR9 := fresh "GR9" in
      let CS12 := fresh "CS12" in
      intros m9 r12 HW9 OUT9 GR9 CS12; unfold LSF in OUT9;
      lazymatch goal with |- realizes _ (mkCfg (mkst _ ?pc _ _) _) _ => let v := eval vm_compute in (bv_unsigned pc) in
        replace pc with (@BV 64 v I : word) by (apply bv_eq; reflexivity) end;
      apply (KONT m9 r12 HW9);
      [ eapply POSTM_trans; [exact PM8s|]; apply (POSTM_sub C A A6 _ _ _ SUB6);
        apply (POSTM_range C A6 m8 md6 m9 (s - 96 - 3376) (s - 96) s CK HW8 OUT9); lia
      | apply (OCC_pw m8 m9 s); [lia | lia | | exact CE8];
        let b := fresh "b" in let n := fresh "n" in let Hb := fresh "Hb" in let Hn := fresh "Hn" in let x := fresh "x" in let Hx := fresh "Hx" in
        intros b n Hb Hn; destruct n as [|n]; [reflexivity|]; apply rdn_ext; rewrite u_Z2bv by lia; [lia|]; intros x Hx; apply OUT9; lia
      | csr; reflexivity | csr; reflexivity | csr; reflexivity | csr; reflexivity
      | let x := fresh "x" in let Hx := fresh "Hx" in
        intros x Hx; cbn [In] in Hx; repeat (destruct Hx as [<-|Hx]; [csr; reflexivity|]); destruct Hx ]
  end.

(* [comment removed for export] *)
Lemma oc_tail_W : forall fr6 cs6 C A A6 (m m6 : word -> option byte) md vm6 regs r8 (s pixs pup plf prot w h cm datas y0 y1 : Z) (cv : cmapv)
    (ret f0 f1 : word) (S : TSet) (kR bR : Z),
  Cok C -> W C A m md -> W C A6 m6 (with_vmmaps vm6 md) -> frm_zero cs6 -> (forall q, live A6 q = live A q) -> POSTM C A s m m6 ->
  (s mod 16 = 0)%Z -> (c_top C - LSTK + 96 + 3600 <= s)%Z -> (s <= c_top C)%Z -> ret_ok ret -> getr regs 2 = Z_to_bv 64 s ->
  getr regs 4 = Z_to_bv 64 0x123d20 ->
  (s <= pup)%Z -> (pup + 4 <= c_top C)%Z -> (s <= plf)%Z -> (plf + 4 <= c_top C)%Z -> (s <= prot)%Z -> (prot + 4 <= c_top C)%Z ->
  (pup + 4 <= plf \/ plf + 4 <= pup)%Z -> (pup + 4 <= prot \/ prot + 4 <= pup)%Z -> (plf + 4 <= prot \/ prot + 4 <= plf)%Z ->
  PIXat m pixs (hdv w h 1 cm datas) -> hdr_ok w h 1 -> (1 <= w)%Z -> (1 <= h)%Z ->
  live A (Z_to_bv 64 pixs) = Some 64%Z -> live A (Z_to_bv 64 datas) = Some (4 * (wpl_of w 1 * h))%Z ->
  (cm = 0%Z \/ (CMAPat m cm cv /\ cmap_ok cv /\ live A (Z_to_bv 64 cm) = Some 24%Z /\ live A (Z_to_bv 64 (c_arr cv)) = Some (4 * c_nalloc cv)%Z)) ->
  OCC m6 s ret (getr regs 8) (getr regs 9) (getr regs 18) (getr regs 19) (getr regs 20) f0 f1 ->
  rdn SEGS m6 (Z_to_bv 64 (s - 72)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 y0)) ->
  rdn SEGS m6 (Z_to_bv 64 (s - 76)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 y1)) ->
  getr r8 2 = Z_to_bv 64 (s - 96) -> getr r8 4 = Z_to_bv 64 0x123d20 -> getr r8 8 = Z_to_bv 64 pixs -> getr r8 9 = Z_to_bv 64 prot ->
  getr r8 18 = Z_to_bv 64 0 -> getr r8 19 = Z_to_bv 64 plf -> getr r8 20 = Z_to_bv 64 pup ->
  (forall x, In x [3; 21; 22; 23; 24; 25; 26; 27]%bv -> getr r8 x = getr regs x) ->
  aroom A6 vm6 (kR + (RK_pixcopy + 3)) (bR + RB_oc_arm w h cm) -> (0 <= kR)%Z -> (0 <= bR)%Z ->
  (forall fr' cs' A' m' vm' regs' (M : word -> option byte), W C A' m' (with_vmmaps vm' md) -> frm_zero cs' -> cs_kept regs regs' ->
     (M = m \/ exists y0 y1 y2 : Z, M = wr4 (wr4 (wr4 m pup y0) plf y1) prot y2) -> POSTM C A s M m' ->
     oc_res C A A' m' regs' cv -> aroom A' vm' kR bR ->
     realizes SEGS (mkCfg (@mkst (mkFP fr' cs') regs' ret m' al_rom) (with_vmmaps vm' md)) S) ->
  realizes SEGS (mkCfg (@mkst (mkFP fr6 cs6) r8 (0x9b254 : word) m6 al_rom) (with_vmmaps vm6 md)) S.
